import React, { useMemo, useState } from 'react'
import useLayerStore from '../../../utils/store'
import { getAssetPartMeta } from '../../../utils/dataV2'
import { getPartPreviewHex } from '../../../utils/color-display'
import ColorSelectModal from '../color-select-modal/color-select-modal'
import {
  AssetPreview,
  AssetBorder,
  LeftArrow,
  RightArrow,
  ColorPreview,
  ButtonContainer,
  SelectorCard,
  SelectorLabel,
} from './item-options.style'

const PartColorSelector = ({
  layerId,
  layerType,
  assetName,
  part,
  showLabel = true,
  labelOverride = null,
}) => {
  const layerArr = useLayerStore((state) => state.layerArr)
  const setSelectedLayer = useLayerStore((state) => state.setSelectedLayer)
  const setLayerPartSelection = useLayerStore((state) => state.setLayerPartSelection)
  const [open, setOpen] = useState(false)
  const liveLayer = layerArr.find((layer) => layer.id === layerId)
  const activePart =
    liveLayer?.parts?.find((currentPart) => currentPart.key === part.key) || part
  const partMeta = useMemo(
    () => getAssetPartMeta(layerType, assetName, activePart.key),
    [layerType, assetName, activePart.key]
  )
  const colorOptions = partMeta?.colorOptions || []
  const currentColorIndex = colorOptions.indexOf(activePart.selection)
  const previewHex = getPartPreviewHex(activePart, '#ffffff')

  const changeSelection = (direction) => {
    if (!colorOptions.length) {
      return
    }

    const safeCurrentIndex = currentColorIndex >= 0 ? currentColorIndex : 0
    const nextIndex =
      (safeCurrentIndex + direction + colorOptions.length) % colorOptions.length

    setLayerPartSelection(layerId, activePart.key, colorOptions[nextIndex])
  }

  return (
    <SelectorCard>
      {showLabel && <SelectorLabel>{labelOverride || activePart.label}</SelectorLabel>}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <ButtonContainer onClick={() => changeSelection(-1)}>
          <LeftArrow />
        </ButtonContainer>
        <AssetBorder isSelected={open}>
          <AssetPreview
            onClick={() => {
              setSelectedLayer(layerId)
              setOpen(true)
            }}
          >
            <ColorPreview color={previewHex || '#ffffff'} />
          </AssetPreview>
        </AssetBorder>
        <ButtonContainer onClick={() => changeSelection(1)}>
          <RightArrow />
        </ButtonContainer>
      </div>
      <ColorSelectModal
        open={open}
        onClose={() => setOpen(false)}
        options={colorOptions}
        selection={activePart.selection}
        partKey={activePart.key}
        layerId={layerId}
      />
    </SelectorCard>
  )
}

export default PartColorSelector
