const imageLoadCache = new Map()
const processedImageCache = new Map()

const clampValue = (value, min, max) => Math.min(max, Math.max(min, value))

const normalizeAdjustments = (adjustments = {}) => ({
  hueShift: clampValue(Number(adjustments.hueShift) || 0, -180, 180),
  saturation: clampValue(Number(adjustments.saturation) || 0, -100, 100),
  lightness: clampValue(Number(adjustments.lightness) || 0, -100, 100),
  opacity: clampValue(
    adjustments.opacity === undefined ? 100 : Number(adjustments.opacity) || 0,
    0,
    100
  ),
  contrast: clampValue(Number(adjustments.contrast) || 0, -100, 100),
})

const hasColorAdjustments = (adjustments) =>
  adjustments.hueShift !== 0 ||
  adjustments.saturation !== 0 ||
  adjustments.lightness !== 0 ||
  adjustments.opacity !== 100 ||
  adjustments.contrast !== 0

const hasHslAdjustments = (adjustments) =>
  adjustments.hueShift !== 0 ||
  adjustments.saturation !== 0 ||
  adjustments.lightness !== 0

const rgbToHsl = (r, g, b) => {
  const rn = r / 255
  const gn = g / 255
  const bn = b / 255
  const max = Math.max(rn, gn, bn)
  const min = Math.min(rn, gn, bn)
  let h = 0
  let s = 0
  const l = (max + min) / 2
  const delta = max - min

  if (delta !== 0) {
    s = delta / (1 - Math.abs(2 * l - 1))

    switch (max) {
      case rn:
        h = 60 * (((gn - bn) / delta) % 6)
        break
      case gn:
        h = 60 * ((bn - rn) / delta + 2)
        break
      default:
        h = 60 * ((rn - gn) / delta + 4)
        break
    }
  }

  if (h < 0) {
    h += 360
  }

  return [h, s * 100, l * 100]
}

const hslToRgb = (h, s, l) => {
  const sn = clampValue(s, 0, 100) / 100
  const ln = clampValue(l, 0, 100) / 100
  const c = (1 - Math.abs(2 * ln - 1)) * sn
  const hh = h / 60
  const x = c * (1 - Math.abs((hh % 2) - 1))
  let rn = 0
  let gn = 0
  let bn = 0

  if (hh >= 0 && hh < 1) {
    rn = c
    gn = x
  } else if (hh >= 1 && hh < 2) {
    rn = x
    gn = c
  } else if (hh >= 2 && hh < 3) {
    gn = c
    bn = x
  } else if (hh >= 3 && hh < 4) {
    gn = x
    bn = c
  } else if (hh >= 4 && hh < 5) {
    rn = x
    bn = c
  } else {
    rn = c
    bn = x
  }

  const m = ln - c / 2

  return [
    Math.round((rn + m) * 255),
    Math.round((gn + m) * 255),
    Math.round((bn + m) * 255),
  ]
}

const loadImage = (src) => {
  if (imageLoadCache.has(src)) {
    return imageLoadCache.get(src)
  }

  const loadPromise = new Promise((resolve, reject) => {
    const image = new Image()
    image.src = src
    image.onload = () => resolve(image)
    image.onerror = reject
  })

  imageLoadCache.set(src, loadPromise)
  return loadPromise
}

const convertCanvasToGrayscale = (context, width, height) => {
  const imageData = context.getImageData(0, 0, width, height)
  const { data } = imageData

  for (let index = 0; index < data.length; index += 4) {
    if (data[index + 3] === 0) {
      continue
    }

    const luminance = Math.round(
      data[index] * 0.299 + data[index + 1] * 0.587 + data[index + 2] * 0.114
    )

    data[index] = luminance
    data[index + 1] = luminance
    data[index + 2] = luminance
  }

  context.putImageData(imageData, 0, 0)
}

const hexToRgb = (hex) => {
  const normalizedHex = hex.replace('#', '')
  const safeHex =
    normalizedHex.length === 3
      ? normalizedHex
          .split('')
          .map((character) => `${character}${character}`)
          .join('')
      : normalizedHex

  return {
    r: Number.parseInt(safeHex.slice(0, 2), 16),
    g: Number.parseInt(safeHex.slice(2, 4), 16),
    b: Number.parseInt(safeHex.slice(4, 6), 16),
  }
}

const applyLuminanceTint = (context, width, height, tintHex) => {
  const imageData = context.getImageData(0, 0, width, height)
  const { data } = imageData
  const tintRgb = hexToRgb(tintHex)

  for (let index = 0; index < data.length; index += 4) {
    if (data[index + 3] === 0) {
      continue
    }

    const luminance =
      (data[index] * 0.299 + data[index + 1] * 0.587 + data[index + 2] * 0.114) / 255
    const shadeFactor = 0.35 + luminance * 0.75

    data[index] = clampValue(Math.round(tintRgb.r * shadeFactor), 0, 255)
    data[index + 1] = clampValue(Math.round(tintRgb.g * shadeFactor), 0, 255)
    data[index + 2] = clampValue(Math.round(tintRgb.b * shadeFactor), 0, 255)
  }

  context.putImageData(imageData, 0, 0)
}

const applyContrast = (value, contrast) => {
  if (contrast === 0) {
    return value
  }

  const contrastAmount = clampValue(contrast, -100, 100) * 2.55
  const factor =
    (259 * (contrastAmount + 255)) / (255 * (259 - contrastAmount))

  return clampValue(Math.round(factor * (value - 128) + 128), 0, 255)
}

const processImageColor = async (
  src,
  tintHex,
  colorAdjustments = {},
  options = {}
) => {
  const normalizedAdjustments = normalizeAdjustments(colorAdjustments)
  const shouldAdjustColors = hasColorAdjustments(normalizedAdjustments)
  const shouldAdjustHsl = hasHslAdjustments(normalizedAdjustments)
  const tintMode = options.tintMode || 'multiply'

  if (!tintHex && !shouldAdjustColors) {
    return src
  }

  const cacheKey = `${src}|${(tintHex || 'none').toLowerCase()}|${normalizedAdjustments.hueShift}|${normalizedAdjustments.saturation}|${normalizedAdjustments.lightness}|${normalizedAdjustments.opacity}|${normalizedAdjustments.contrast}|${tintMode}`

  if (processedImageCache.has(cacheKey)) {
    return processedImageCache.get(cacheKey)
  }

  const processedPromise = loadImage(src).then((image) => {
    const canvas = document.createElement('canvas')
    canvas.width = image.width
    canvas.height = image.height
    const context = canvas.getContext('2d')
    context.imageSmoothingEnabled = false
    context.drawImage(image, 0, 0)

    if (tintHex) {
      if (tintMode === 'luminance-map') {
        applyLuminanceTint(context, canvas.width, canvas.height, tintHex)
      } else {
        if (tintMode === 'grayscale-multiply') {
          convertCanvasToGrayscale(context, canvas.width, canvas.height)
        }

        context.globalCompositeOperation = 'multiply'
        context.fillStyle = tintHex
        context.fillRect(0, 0, canvas.width, canvas.height)
        context.globalCompositeOperation = 'destination-in'
        context.drawImage(image, 0, 0)
        context.globalCompositeOperation = 'source-over'
      }
    }

    if (shouldAdjustHsl) {
      const imageData = context.getImageData(0, 0, canvas.width, canvas.height)
      const { data } = imageData
      for (let index = 0; index < data.length; index += 4) {
        if (data[index + 3] === 0) {
          continue
        }

        const [h, s, l] = rgbToHsl(data[index], data[index + 1], data[index + 2])
        const adjustedHue = (h + normalizedAdjustments.hueShift + 360) % 360
        const adjustedSaturation = clampValue(
          s + normalizedAdjustments.saturation,
          0,
          100
        )
        const adjustedLightness = clampValue(
          l + normalizedAdjustments.lightness,
          0,
          100
        )
        const [nr, ng, nb] = hslToRgb(
          adjustedHue,
          adjustedSaturation,
          adjustedLightness
        )

        data[index] = applyContrast(nr, normalizedAdjustments.contrast)
        data[index + 1] = applyContrast(ng, normalizedAdjustments.contrast)
        data[index + 2] = applyContrast(nb, normalizedAdjustments.contrast)
        data[index + 3] = clampValue(
          Math.round(data[index + 3] * (normalizedAdjustments.opacity / 100)),
          0,
          255
        )
      }

      context.putImageData(imageData, 0, 0)
    } else if (normalizedAdjustments.opacity !== 100 || normalizedAdjustments.contrast !== 0) {
      const imageData = context.getImageData(0, 0, canvas.width, canvas.height)
      const { data } = imageData

      for (let index = 0; index < data.length; index += 4) {
        if (data[index + 3] === 0) {
          continue
        }

        data[index] = applyContrast(data[index], normalizedAdjustments.contrast)
        data[index + 1] = applyContrast(data[index + 1], normalizedAdjustments.contrast)
        data[index + 2] = applyContrast(data[index + 2], normalizedAdjustments.contrast)
        data[index + 3] = clampValue(
          Math.round(data[index + 3] * (normalizedAdjustments.opacity / 100)),
          0,
          255
        )
      }

      context.putImageData(imageData, 0, 0)
    }

    return canvas.toDataURL('image/png')
  })

  processedImageCache.set(cacheKey, processedPromise)
  return processedPromise
}

export {
  clampValue,
  hasColorAdjustments,
  normalizeAdjustments,
  processImageColor,
}
