import React, { useEffect, useState } from 'react'
import useLayerStore from '../../../utils/store'
import SkinColors from '../../../utils/skinColors'
import { getPartPreviewHex } from '../../../utils/color-display'
import DarkBorder from '../../border-container/dark-border-container'
import useOptionsStore from '../../options/utils/options-store'

import {
  CompactControls,
  EyesContainer,
  TextContainer,
  LeftArrow,
  RightArrow,
  ColorPreview,
  PreviewContainer,
  ButtonContainer,
  InnerContainer,
} from './eyes.style'

const Skin = ({ compact = false }) => {
  const layerArr = useLayerStore((state) => state.layerArr)
  const setAllBodyColor = useLayerStore((state) => state.setAllBodyColor)
  const setSelectedLayer = useLayerStore((state) => state.setSelectedLayer)
  const setOptionsState = useOptionsStore((state) => state.setOptionsState)
  const [hex, setHex] = useState('#f3d6ba')
  const bodyEditorLayer = layerArr.find(
    (layer) => layer.layerType === 'Body' && layer.isBaseLayer
  )
  const currentBodyColor = bodyEditorLayer?.parts?.[0]?.selection || SkinColors[0].fileName

  const openBodyColorEditor = () => {
    if (!bodyEditorLayer) {
      return
    }

    setSelectedLayer(bodyEditorLayer.id)
    setOptionsState('item')
  }

  const incrementSkinColor = () => {
    const skinIndex = SkinColors.findIndex(
      (skinColor) => skinColor.fileName === currentBodyColor
    )
    const nextColor =
      skinIndex === SkinColors.length - 1
        ? SkinColors[0].fileName
        : SkinColors[skinIndex + 1].fileName
    setAllBodyColor(nextColor)
  }

  const decrementSkinColor = () => {
    const skinIndex = SkinColors.findIndex(
      (skinColor) => skinColor.fileName === currentBodyColor
    )
    const nextColor =
      skinIndex <= 0
        ? SkinColors[SkinColors.length - 1].fileName
        : SkinColors[skinIndex - 1].fileName
    setAllBodyColor(nextColor)
  }

  useEffect(() => {
    setHex(getPartPreviewHex(bodyEditorLayer?.parts?.[0], SkinColors[0]?.hex || '#f3d6ba'))
  }, [bodyEditorLayer, currentBodyColor])

  return (
    <EyesContainer compact={compact}>
      <TextContainer compact={compact} className='font-face-gm'>
        Skin
      </TextContainer>
      <CompactControls compact={compact}>
        <ButtonContainer compact={compact} onClick={() => decrementSkinColor()}>
          <InnerContainer>
            <LeftArrow compact={compact} />
          </InnerContainer>
        </ButtonContainer>
        <PreviewContainer
          compact={compact}
          onClick={() => openBodyColorEditor()}
          style={{ cursor: 'pointer' }}
        >
          <DarkBorder>
            <ColorPreview compact={compact} hex={hex} />
          </DarkBorder>
        </PreviewContainer>
        <ButtonContainer compact={compact} onClick={() => incrementSkinColor()}>
          <InnerContainer>
            <RightArrow compact={compact} />
          </InnerContainer>
        </ButtonContainer>
      </CompactControls>
    </EyesContainer>
  )
}

export default Skin
