import styled from '@emotion/styled'
import AboutLogo from '../../../monochrome/borderless/about.png'
import PatreonLogo from '../../../monochrome/borderless/patreon.png'
import DiscordLogo from '../../../monochrome/borderless/discord.png'
import EmailLogo from '../../../monochrome/borderless/email.png'

const ConnectContainer = styled.div`
  width: calc(100% - 40px);
  height: 44px;
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  @media screen and (max-width: 1320px) {
    grid-area: 6 / 1 / 7 / 3;
    width: 100%;
    padding: 4px 6px 6px;
    box-sizing: border-box;
    margin-bottom: 0;
    height: auto;
    justify-content: space-between;
    gap: 10px;
  }
`
const IconsContainer = styled.div`
  width: calc(100% - 120px);
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  & > * {
    height: 48px !important;
    width: 48px !important;
  }
  @media screen and (max-width: 919px) {
    width: calc(100% - 82px);
    gap: 0;
    justify-content: space-between;
    & > * {
      height: 40px !important;
      width: 40px !important;
    }
  }
`
const TextDiv = styled.div`
  width: 120px;
  color: ${({ theme }) => theme.palette.white.main};
  display: flex;
  flex-direction: column;
  align-items: center;
  @media screen and (max-width: 919px) {
    width: 72px;
    font-size: 11px;
    line-height: 1.1;
    align-items: flex-start;
  }
`
const About = styled.div`
  height: 36px;
  width: 36px;
  background-image: url(${AboutLogo});
  background-repeat: no-repeat;
  background-position: center;
  background-size: 100% 100%;
  image-rendering: pixelated;
`
const Patreon = styled.div`
  height: 36px;
  width: 36px;
  background-image: url(${PatreonLogo});
  background-repeat: no-repeat;
  background-position: center;
  background-size: 100% 100%;
  image-rendering: pixelated;
`
const Discord = styled.div`
  height: 36px;
  width: 36px;
  background-image: url(${DiscordLogo});
  background-repeat: no-repeat;
  background-position: center;
  background-size: 100% 100%;
  image-rendering: pixelated;
`
const Email = styled.div`
  height: 36px;
  width: 36px;
  background-image: url(${EmailLogo});
  background-repeat: no-repeat;
  background-position: center;
  background-size: 100% 100%;
  image-rendering: pixelated;
`
const ButtonContainer = styled.div`
  height: 48px !important;
  width: 48px !important;
  @media screen and (max-width: 919px) {
    height: 40px !important;
    width: 40px !important;
  }
  &:hover {
    cursor: pointer;
    & > * {
      background-color: ${({ theme }) => theme.palette.primary.alternate};
      & > * {
        background-color: ${({ theme }) => theme.palette.secondary.main};
      }
    }
  }
`

export {
  ConnectContainer,
  IconsContainer,
  TextDiv,
  About,
  Patreon,
  Discord,
  Email,
  ButtonContainer
}
